import{_ as n}from"./chunks/picker-pick.C3z1OD5-.js";import{_ as s,C as r,o as i,c as l,j as t,a as h,E as c,a6 as o}from"./chunks/framework.CCKCzdWs.js";const d="/videos/picker-pick-loop.mp4",x=JSON.parse('{"title":"Pick an element","description":"Pick an element on the live page with Piwi Picker: its ranked locators, each checked against the page, with the action, the assertion and the context a test or an agent needs.","frontmatter":{"title":"Pick an element","description":"Pick an element on the live page with Piwi Picker: its ranked locators, each checked against the page, with the action, the assertion and the context a test or an agent needs.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/features/pick-an-element.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/features/pick-an-element.html"}],["meta",{"property":"og:title","content":"Pick an element | Piwi for Playwright"}],["meta",{"property":"og:description","content":"Pick an element on the live page with Piwi Picker: its ranked locators, each checked against the page, with the action, the assertion and the context a test or an agent needs."}]]},"headers":[],"relativePath":"features/pick-an-element.md","filePath":"features/pick-an-element.md","lastUpdated":1795281128000}'),p={name:"features/pick-an-element.md"};function g(m,e,f,u,k,w){const a=r("Needs");return i(),l("div",null,[e[0]||(e[0]=t("h1",{id:"pick-an-element",tabindex:"-1"},[h("Pick an element "),t("a",{class:"header-anchor",href:"#pick-an-element","aria-label":'Permalink to "Pick an element"'},"​")],-1)),c(a,{extension:""}),e[1]||(e[1]=o('<p><strong>Pick an element</strong>, in the <a href="./extension.html">Piwi Picker</a> popup or with its shortcut, ranks the Playwright locators of one element of the page you are looking at, checks each against the page, and writes what a test needs around it. This page is where the pick itself, the narrowing of a locator that finds several elements and the copy forms are explained; the <a href="./devtools.html#the-elements-sidebar">DevTools sidebar</a>, the <a href="./lint-overlay.html">lint overlay</a> and the <a href="./tested-elements.html">Tested elements</a> replacements reuse them.</p><figure><img src="'+n+'" alt="The ranked locators of a Checkout button, the unique one first"><figcaption>Pick an element: the locator that finds exactly one element comes first.</figcaption></figure><h2 id="how-a-pick-works" tabindex="-1">How a pick works <a class="header-anchor" href="#how-a-pick-works" aria-label="Permalink to &quot;How a pick works&quot;">​</a></h2><p>Hover highlights, a click picks. The pick snaps to the nearest actionable ancestor (the text inside a button picks the button), and ↑/↓ walk the DOM tree, showing the locator each step would produce. When a locator that is not brittle already finds the element alone, the results open at once, and <strong>Scope to a parent…</strong> in them opens the <strong>anchors</strong> step: stable parents to scope the locator to, each listed with its strongest hook (a test id, an <code>id</code>, a labeled landmark, a role), with a live match count, after which the results show again with the scoped locators. When none finds it alone, the anchors step comes first.</p>',4)),e[2]||(e[2]=t("figure",null,[t("video",{src:d,autoplay:"",loop:"",muted:"",playsinline:"",controls:"","aria-label":"Picking on a shop page: the outline and the locator follow the pointer, the arrow keys walk up to the parents and back, and a click on Checkout opens its ranked locators"}),t("figcaption",null,"Hover, walk the tree with ↑ and ↓, click: the ranked locators open.")],-1)),e[3]||(e[3]=o('<p><strong>Enter</strong> picks too: the highlighted element when the pointer is on one, otherwise the element that has the keyboard focus, so a control reached with Tab is picked without the mouse. <strong>Esc</strong> cancels the pick.</p><p>Elements inside a web component&#39;s open shadow root are picked like any other: ↑ walks out of the shadow root through its host element, and the anchors step lists the host and its parents and counts the matches inside open shadow roots, as Playwright&#39;s locators do.</p><p>Every candidate uses the names Playwright computes (a tab with a count badge is <code>{ name: &#39;Regressions 5&#39; }</code>), is scored as the dashboard scores locators, and run against the page. Those that find only the picked element come first; a narrowed one ranks just under the candidate it was built from.</p><h2 id="narrowing-a-locator-that-finds-several" tabindex="-1">Narrowing a locator that finds several <a class="header-anchor" href="#narrowing-a-locator-that-finds-several" aria-label="Permalink to &quot;Narrowing a locator that finds several&quot;">​</a></h2><p>A candidate that finds the picked element among others is narrowed, trying in this order and keeping the first that finds the element alone:</p><ol><li><strong>Exact</strong>: the name or text matched exactly (<code>exact: true</code>).</li><li><strong>The element&#39;s own text</strong>: <code>.filter({ hasText })</code> with its text, when that text is short. Controls that share a name often still say different things.</li><li><strong>A parent with a test id unique on the page</strong>, the author&#39;s own hook.</li><li><strong>The repeated row, list item or card</strong> the element sits in: the nearest ancestor whose copies hold the other elements the candidate finds. The copies are recognized by a shared test id, else a shared tag and role, else a shared readable class. The container is picked by its own accessible name when its author gave it one (<code>aria-label</code>, <code>aria-labelledby</code>), else by a short text it shows and no other copy contains: a heading first, then a text that names rather than counts (a name before a price or a quantity), the shorter first, and a visible text before a hidden one: <code>getByTestId(&#39;product-card&#39;).filter({ hasText: &#39;Blue mug&#39; }).getByRole(&#39;button&#39;, { name: &#39;Add to cart&#39; })</code>.</li><li><strong>The nearest landmark</strong>, or a named dialog, region, form, row, list item or other named group around it.</li></ol><p>Only when none of these finds it alone is it offered with <code>.first()</code> or <code>.nth()</code>, and a warning, which the <a href="/reference/locator-stability.html">stability rules</a> mark as a position.</p><h2 id="the-results" tabindex="-1">The results <a class="header-anchor" href="#the-results" aria-label="Permalink to &quot;The results&quot;">​</a></h2><p>While the results are open, the picked element stays outlined on the page, and the results move to the other side of the page when they would cover it. <strong>Pick another</strong> closes them and starts picking the next element, without going back to the popup or the shortcut.</p><p>Each locator leads with a word: <code>stable</code>, <code>watch</code> or <code>brittle</code> for one that finds the element alone, by what the <a href="/reference/locator-stability.html#levels">stability rules</a> say of it, and <code>unique by position</code>, <code>3 matches</code> or <code>not checked</code> otherwise, the words the DevTools sidebar uses. Its <strong>Details</strong> give the reasons (<code>unique · brittle: CSS class</code>) and the stability score.</p><h2 id="copy-as-a-locator-an-action-or-an-assertion" tabindex="-1">Copy as a locator, an action or an assertion <a class="header-anchor" href="#copy-as-a-locator-an-action-or-an-assertion" aria-label="Permalink to &quot;Copy as a locator, an action or an assertion&quot;">​</a></h2><p>Every locator Piwi Picker offers, here, in the DevTools sidebar and in the Locators console, copies three ways, and each button names what it writes, such as <strong>Action (fill)</strong> or <strong>Assertion (toHaveText)</strong>:</p><ul><li><strong>Locator</strong>: <code>page.</code> and the locator.</li><li><strong>Action</strong>: the call the element calls for, <code>fill</code> with what a field holds (<code>&#39;value&#39;</code> for an empty field or a password), <code>check</code> for a checkbox or a radio, <code>selectOption</code> for a select (an array for several options), <code>click</code> for anything else.</li><li><strong>Assertion</strong>: the element&#39;s first <a href="#assertion-suggester">suggestion</a> (<code>not.toBeChecked</code> for an unchecked box), and <code>toHaveCount</code> for a locator that finds several elements.</li></ul><p>Where the element is not known, the action is a <code>click</code> and the assertion <code>toBeVisible</code>. <strong>Copy all</strong> copies every ranked locator, one per line, for a project&#39;s <a href="./locator-usage.html#the-locators-page">Locators page</a>. <strong>Add to session</strong> names a locator for the session that the DevTools Piwi panel&#39;s Session tab lists and copies as a page object, as the Elements sidebar does (see <a href="./devtools.html">Developer tools</a>).</p><h2 id="multi-pick" tabindex="-1">Multi-pick <a class="header-anchor" href="#multi-pick" aria-label="Permalink to &quot;Multi-pick&quot;">​</a></h2><p>Pick two or three similar items (rows, cards) to get the pattern they share, such as <code>getByRole(&#39;row&#39;).filter({ hasText: … })</code>. Pick the same button in two rows or cards (Delete, Add to cart) and the pattern is the button inside the repeated row or card, with how many elements it finds on the page: <code>getByTestId(&#39;product-card&#39;).getByRole(&#39;button&#39;, { name: &#39;Add to cart&#39; })</code>, then each pick as its card filtered by a text only that card shows, such as its heading. It warns when only <code>.nth()</code> could tell them apart.</p><h2 id="assertion-suggester" tabindex="-1">Assertion suggester <a class="header-anchor" href="#assertion-suggester" aria-label="Permalink to &quot;Assertion suggester&quot;">​</a></h2><p>With the popup&#39;s <strong>Assertions</strong> tile, pick an element to get the <code>expect(...)</code> candidates that apply to it, most telling first (<code>toHaveValue</code>, <code>toBeChecked</code>, <code>toContainText</code> with the start of a long text, <code>toHaveText</code>, <code>toHaveAccessibleName</code>, <code>toBeVisible</code>), built on its top-ranked locator. <code>toHaveAccessibleName</code> is offered only for an element that has a name, as Playwright computes it: a paragraph takes none from its text, a field takes its label&#39;s.</p><h2 id="copy-context-for-agent" tabindex="-1">Copy context for agent <a class="header-anchor" href="#copy-context-for-agent" aria-label="Permalink to &quot;Copy context for agent&quot;">​</a></h2><p>With the popup&#39;s <strong>Agent context</strong> tile, pick an element to copy one block for a coding agent: the page URL, the element and every ranked locator.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./extension.html">Browser extension</a>: the other tools, the permissions and the limits</li><li><a href="./devtools.html">Developer tools</a>: the same ranking for the element selected in DevTools</li><li><a href="./lint-overlay.html">Lint overlay</a>: the elements no stable locator finds alone</li><li><a href="/reference/locator-stability.html">Locator stability</a>: the rules behind the words</li><li><a href="/recipes/broken-locator.html">Fix a broken locator</a>: from a failing locator to the one to use instead</li></ul>',22))])}const v=s(p,[["render",g]]);export{x as __pageData,v as default};
